#include "projection_residual_certificate.hpp"
using namespace symrep;
int main(int argc,char**argv){try{Mat P(2,2),B(2,3);P[0].push_back(0,Q(2,3));P[0].push_back(1,Q(-5,7));P[1].push_back(0,Q(-1,11));B[0].push_back(0,Q(3,5));B[0].push_back(1,Q(7));B[1].push_back(1,Q(14,5));B[1].push_back(2,Q(9,13));auto D=mul(P,B);auto c=projection_certificate::certify(D,P,B);require(c.primes>0,"expected modular check");auto bad=D;bad[0][0]+=1;bool rejected=false;try{projection_certificate::certify(bad,P,B);}catch(const std::exception&){rejected=true;}require(rejected,"bad coefficient accepted");Mat p(1,1),b(1,1),d(1,1);p[0].push_back(0,Q(1));b[0].push_back(0,Q(1));auto prime=n_nextprime(1ULL<<60,0);d[0].push_back(0,Q(int_t(prime)+1));rejected=false;try{projection_certificate::certify(d,p,b);}catch(const std::exception&){rejected=true;}require(rejected,"first-prime alias accepted without enough height");Mat z(1,1);auto zero=projection_certificate::certify(z,z,z);require(zero.bound==0&&zero.primes==0,"zero certificate");std::cout<<"ALL_CONTROLS_PASS rational_fixture,bad_coefficient,first_prime_alias,zero_matrix\n";
 if(argc==4){auto d0=read_matrix(argv[1]),p0=read_matrix(argv[2]),b0=flatten(read(argv[3]));auto result=projection_certificate::certify(d0,p0,b0);std::cout<<"FILE_CERTIFICATE_PASS primes="<<result.primes<<" bound="<<result.bound<<" modulus="<<result.modulus<<std::endl;}
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
